let text = ($input.first().json.output) || '';
text = text.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
text = text.split('\n').map(function (line) {
  const t = line.trim();
  if (t.toUpperCase().indexOf('FILE:') === 0) {
    const rest = t.slice(5);
    const bar = rest.indexOf('|');
    if (bar !== -1) {
      const label = rest.slice(0, bar).trim() || 'File';
      const url = rest.slice(bar + 1).trim();
      if (url) return '📎 <a href="' + url + '">' + label + '</a>';
    }
  }
  return line;
}).join('\n');
text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');
text = text.replace(/(^|[\s(])(https?:\/\/[^\s<]+)/g, '$1<a href="$2">$2</a>');
text = text.replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>');
text = text.replace(/__([^_]+)__/g, '<b>$1</b>');
text = text.replace(/\*([^*]+)\*/g, '<i>$1</i>');
while (text.indexOf('\n\n\n') !== -1) text = text.split('\n\n\n').join('\n\n');
text = text.trim();
return [{ json: { output: text } }];

// Classify each link: Drive folder / Drive single file / plain http file.
const out = ($input.first().json.output) || '';
const chatId = $('Edit Fields').first().json.chatId;
const knownExt = ['pdf','jpg','jpeg','png','webp','gif','bmp','doc','docx','xls','xlsx','ppt','pptx','zip','csv','txt'];
const items = [];
const seen = {};
const cand = [];
let m;
const reMd = /\[([^\]]+)\]\(([^)]+)\)/g;
while ((m = reMd.exec(out)) !== null) cand.push({ label: m[1].trim(), url: m[2].trim() });
out.split('\n').forEach(function (line) {
  const t = line.trim();
  if (t.toUpperCase().indexOf('FILE:') === 0) {
    const rest = t.slice(5); const bar = rest.indexOf('|');
    if (bar !== -1) cand.push({ label: rest.slice(0, bar).trim(), url: rest.slice(bar + 1).trim() });
  }
});
const reUrl = /(https?:\/\/[^\s)<>\]]+)/g;
while ((m = reUrl.exec(out)) !== null) cand.push({ label: '', url: m[1] });

for (const c of cand) {
  let url = String(c.url).trim();
  while (url.length && ')>].,;"'.indexOf(url[url.length - 1]) !== -1) url = url.slice(0, -1);
  if (url.toLowerCase().indexOf('http') !== 0 || seen[url]) continue;
  seen[url] = true;
  const low = url.toLowerCase();
  const label = c.label;
  const fIdx = low.indexOf('/drive/folders/');
  if (fIdx !== -1) {
    const folderId = url.slice(fIdx + 15).split('/')[0].split('?')[0].split('#')[0];
    if (folderId) items.push({ json: { source: 'folder', folderId: folderId, label: label || 'Folder' } });
    continue;
  }
  if (low.indexOf('drive.google.com') !== -1 || low.indexOf('docs.google.com') !== -1) {
    let id = '';
    const dpos = url.indexOf('/d/');
    if (dpos !== -1) id = url.slice(dpos + 3).split('/')[0].split('?')[0];
    if (!id) { const qp = url.split('id='); if (qp.length > 1) id = qp[1].split('&')[0]; }
    if (id) items.push({ json: { source: 'drivefile', fileId: id, label: label || 'File' } });
    continue;
  }
  const pathPart = url.split('?')[0].split('#')[0];
  let seg = pathPart.substring(pathPart.lastIndexOf('/') + 1);
  try { seg = decodeURIComponent(seg); } catch (e) {}
  let ext = '';
  const dot = seg.lastIndexOf('.');
  if (dot !== -1) { const e = seg.slice(dot + 1).toLowerCase(); if (knownExt.indexOf(e) !== -1) ext = e; }
  items.push({ json: { source: 'httpfile', downloadUrl: url, label: label || (seg.indexOf('.') !== -1 ? seg : 'File'), ext: ext } });
}
return items;

const mimeToExt = {
  'application/pdf':'pdf','image/jpeg':'jpg','image/png':'png','image/webp':'webp',
  'image/gif':'gif','image/bmp':'bmp','application/msword':'doc',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document':'docx',
  'application/vnd.ms-excel':'xls',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'xlsx',
  'application/vnd.ms-powerpoint':'ppt',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation':'pptx',
  'application/zip':'zip','text/csv':'csv','text/plain':'txt'
};
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const bin = item.binary ? item.binary.data : null;
  if (!bin) continue;
  const mime = bin.mimeType ? String(bin.mimeType).split(';')[0].trim().toLowerCase() : '';
  if (mime === 'text/html' || (bin.fileExtension && String(bin.fileExtension).toLowerCase().indexOf('htm') === 0)) continue;
  let rawName = j.name || j.label || bin.fileName || 'file';
  let ext = j.ext || '';
  if (!ext && String(rawName).indexOf('.') !== -1) { const e = String(rawName).split('.').pop().toLowerCase(); if (e.length <= 5) ext = e; }
  if (!ext && bin.fileExtension) ext = String(bin.fileExtension).toLowerCase().replace('.', '');
  if (!ext && mime) ext = mimeToExt[mime] || '';
  let base = String(rawName).replace(/[\\/:*?"<>|]+/g, ' ').replace(/\s+/g, ' ').trim() || 'file';
  if (ext && base.toLowerCase().endsWith('.' + ext)) base = base.slice(0, -(ext.length + 1));
  const fileName = ext ? base + '.' + ext : base;
  bin.fileName = fileName;
  j.fileName = fileName;
  j.label = base;
  out.push(item);
}
return out;
